class Immunization:
    def __init__(self, immunization, administration_date, vaccine_status, immunization_status):
        self.immunization = immunization
        self.administration_date = administration_date
        self.vaccine_status = vaccine_status
        self.immunization_status = immunization_status

    def __str__(self):
        return f"Immunization: {self.immunization}, Administration date: {self.administration_date}, Vaccine status: {self.vaccine_status}, Immunization status: {self.immunization_status}"

