from typing import List

class PatientRecord:
    def __init__(self, patient_record: dict):
        self.patient_record = patient_record

    def __repr__(self):
        return f"PatientRecord({self.patient_record})"

class Patient:
    def __init__(self, patient_record: dict):
        self.patient_record = patient_record

    def __repr__(self):
        return f"Patient({self.patient_record})"

def extract_patient_info(note: str) -> PatientRecord:
    patient_record = note.split("\n")[-1].split(":")[0].split(" ")
    return PatientRecord(patient_record)

def extract_patient_info_from_note(note: str) -> Patient:
    patient_record = extract_patient_info(note)
    return patient_record

def extract_patient_info_from_note_and_record(note: str) -> Patient:
    patient_record = extract_patient_info(note)
    return patient_record.patient_record

def extract_patient_info_from_note_and_record_and_record(note: str) -> Patient:
    patient_record = extract_patient_info(note)
    return patient_record.patient_record, patient_record.patient_record

def extract_patient_info_from_note_and_record_and_record_and_record(note: str) -> Patient:
